local player = game:GetService("Players").LocalPlayer
local rs = game:GetService("ReplicatedStorage")

local banned = rs:WaitForChild("PlayerStats"):WaitForChild(player.Name):WaitForChild("Banned")
local adminEvent = rs:WaitForChild("Events"):WaitForChild("ADMIN")

local DEBUG = true

local char, humanoid, hrp

local function SetupCharacter()
    char = player.Character or player.CharacterAdded:Wait()
    humanoid = char:WaitForChild("Humanoid")
    hrp = char:WaitForChild("HumanoidRootPart")
end

SetupCharacter()
player.CharacterAdded:Connect(SetupCharacter)
    
local oldIndex; oldIndex = hookmetamethod(game, "__index", function(self, key)
    if not checkcaller() then
        if self == banned and key == "Value" then
            if DEBUG then
                warn("[AC-Bypasser]: Anti-Cheat attempted to check if your banned. Value spoofed to true.")
            end
            return true
        end
    end
    
    return oldIndex(self, key)
end)
    
local oldNamecall; oldNamecall = hookmetamethod(game, "__namecall", function(self, ...)
    if not checkcaller() then
        local args = { ... }
        local method = getnamecallmethod()
        if self == adminEvent and method == "FireServer" and args[1] == "Checking" then
            if DEBUG then
                warn("[AC-Bypasser]: Anti-Cheat attempted to send a remote to ban you. Remote blocked")
            end
            return
        elseif typeof(self) == "Instance" and self.IsA(self, "AnimationTrack") and self.Animation.AnimationId == "rbxassetid://73126877562422" and method == "Play" then
            if DEBUG then
                warn("AC-Bypasser]: Anti-Cheat attempted to fallback to a animation track to ban you. Remote blocked.")
            end
            return 
        end
    end
    
    return oldNamecall(self, ...)
end)  

